import {savedManagerDrivers} from './manager-drivers.js?v=0.24.0';
import {dispatchCall,openDispatchView} from './dispatch.js?v=0.24.0';
import {csvCell} from './domain.js?v=0.24.0';
import {bindCounterAwake} from './counter-tools.js?v=0.24.0';
const root=document.querySelector('#management'),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const expandedOrders=new Set();
const formatTime=v=>v&&Number.isFinite(Date.parse(v))?new Date(v).toLocaleString():'not recorded';
let drivers=savedManagerDrivers(localStorage),selected=drivers[0]?.id,view=null,message='',loading=false;
try{const id=JSON.parse(localStorage.getItem('delivery-manager-manager-v1')||'null')?.id;if(drivers.some(d=>d.id===id))selected=id;}catch{}
function render(){root.querySelectorAll('details[data-order]').forEach(d=>d.open?expandedOrders.add(d.dataset.order):expandedOrders.delete(d.dataset.order));const summary=view?.shiftSummary;root.innerHTML=`<header class="manager-brand"><img src="icon.svg" alt=""><div><h1>Convey Management</h1><p>The latest shared shift, in one place.</p></div></header><nav class="actions"><a class="button-link" href="manager.html">Back to Dispatch</a><button id="counter-awake">Keep screen awake</button><small id="counter-awake-status" role="status"></small></nav>${drivers.find(d=>d.id===selected)?.mode==='test'?'<div class="demo-banner">TEST MANAGEMENT · fictional records</div>':''}${drivers.length?`<section class="card"><label for="admin-driver">Driver</label><select id="admin-driver">${drivers.map(d=>`<option value="${esc(d.id)}" ${d.id===selected?'selected':''}>${esc(d.driverName||'Driver')} · ${esc(d.mode)}</option>`).join('')}</select><button id="admin-refresh" ${loading?'disabled':''}>Refresh</button><p role="status">${esc(message)}</p><p class="muted">Updates require the driver app to sync. This is a latest-shift overview, not a live location tracker or a complete historical archive. Driver tips and reimbursement rates are excluded.</p></section>`:'<section class="card"><p>Connect drivers in Dispatch first.</p><a href="manager.html">Connect a driver</a></section>'}${summary?`<section class="card"><h2>${summary.status==='active'?'Current shift':'Latest completed shift'}</h2><p>Started ${esc(new Date(summary.startedAt).toLocaleString())}</p><div class="metrics management-metrics"><div class="metric"><strong>${summary.activeOrders}</strong><small>Out for delivery</small></div><div class="metric"><strong>${summary.completedOrders}</strong><small>Orders delivered</small></div><div class="metric"><strong>${summary.heldOrders}</strong><small>Scheduled holds</small></div><div class="metric"><strong>${summary.actualMiles??'—'}</strong><small>Final actual miles</small></div></div><h3>Tasks completed</h3><ul>${summary.tasks.map(t=>`<li>${esc(t)}</li>`).join('')||'<li>No tasks recorded.</li>'}</ul><button id="admin-export" class="primary">Export this shared shift CSV</button></section><section class="card"><h2>Orders & delivery status</h2>${view.orders.map(d=>`<details class="card" data-order="${esc(d.id)}" ${expandedOrders.has(d.id)?'open':''}><summary><strong>${esc(d.name||'Delivery')}</strong> · ${d.scheduleHold?'Ready · scheduled hold':d.status==='active'?'Out for delivery':esc(d.status)}</summary><p>${esc(d.address)}</p>${d.phone?`<p>${esc(d.phone)}</p>`:''}<p>Ticket ${esc(d.ticket||'not recorded')}</p><p>Added ${esc(formatTime(d.enteredAt))}<br>Ready ${esc(formatTime(d.readyAt))}<br>Departed ${esc(formatTime(d.departedAt))}<br>Delivered ${esc(formatTime(d.completedAt))}</p>${d.scheduledAt?`<p>Requested arrival ${esc(new Date(d.scheduledAt).toLocaleString())}</p>`:''}<ul>${(d.items||[]).map(i=>`<li>${i.quantity} × ${esc(i.name)}</li>`).join('')}</ul>${d.hasAlcohol?'<p>Alcohol · Check ID · signature receipt required</p>':''}${d.hasColdItems?`<p>Drinks / ice cream: ${esc(d.coldItemDetails)}</p>`:''}${d.notes?`<p>${esc(d.notes)}</p>`:''}</details>`).join('')}${view.omitted?`<p>${view.omitted} orders omitted by shared-view size limit.</p>`:''}</section>`:''}<section class="card"><h2>Access & permissions</h2><p>Access currently comes from each driver’s private pairing. This page can read the shared shift and export it. Dispatch can add orders and request readiness, batch and route changes for its own unstarted orders. Driver-created orders are view-only.</p><p class="muted">Owner/staff roles, permission editing, revocation from an owner account and historical report access are the next admin phase. They are not enabled in this foundation. No private tip or reimbursement permission is granted here.</p></section>`;bindCounterAwake();const select=document.querySelector('#admin-driver');if(select)select.onchange=()=>{selected=select.value;view=null;refresh();};if(document.querySelector('#admin-refresh'))document.querySelector('#admin-refresh').onclick=refresh;if(document.querySelector('#admin-export'))document.querySelector('#admin-export').onclick=exportReport;}
async function refresh(){const config=drivers.find(d=>d.id===selected);if(!config||loading)return;loading=true;message='Checking shared status…';render();try{const response=await dispatchCall('view',{},config.token);const next=response.view?await openDispatchView(config,response.view):null;if(selected!==config.id)return;view=next;message=view?'Driver last synced '+new Date(response.view.updated_at).toLocaleString():'No shared shift yet. Open the updated driver app.';}catch(e){message=e.message;}finally{loading=false;render();}}
function exportReport(){if(!view?.shiftSummary)return;const s=view.shiftSummary,rows=[['record_type','shift_id','driver','status','started_at','ended_at','actual_miles','delivery_id','customer_name','phone','address','ticket','ready_at','departed_at','delivered_at','scheduled_at','schedule_hold','items','notes','tasks']],name=drivers.find(d=>d.id===selected)?.driverName||'';rows.push(['shift',s.id,name,s.status,s.startedAt,s.endedAt,s.actualMiles,'','','','','','','','','','','','',s.tasks.join('; ')]);for(const d of view.orders)rows.push(['delivery',s.id,name,d.status,'','','',d.id,d.name,d.phone,d.address,d.ticket,d.readyAt,d.departedAt,d.completedAt,d.scheduledAt,d.scheduleHold?'YES':'NO',(d.items||[]).map(i=>i.quantity+' × '+i.name).join('; '),d.notes,'']);const url=URL.createObjectURL(new Blob(['\ufeff'+rows.map(r=>r.map(csvCell).join(',')).join('\r\n')+'\r\n'],{type:'text/csv;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download='Convey-shared-shift-'+s.id+'.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),2000);}
render();if(selected)refresh();setInterval(()=>{if(!document.hidden)refresh();},15000);
